        private boolean confirmLeave(){if(!session.dirty)return true;if(session.transientDesktop){int choice=JOptionPane.showOptionDialog(this,"Adjustments for NPC "+project.npcId+" have not been exported.\nSwitching or closing will discard them.","Discard unexported adjustments?",JOptionPane.DEFAULT_OPTION,JOptionPane.WARNING_MESSAGE,null,new String[]{"Discard Adjustments","Keep Editing"},"Keep Editing");return choice==0;}int choice=JOptionPane.showConfirmDialog(this,"Save changes to "+session.projectFile.getFileName()+" before continuing?","Unsaved changes",JOptionPane.YES_NO_CANCEL_OPTION,JOptionPane.WARNING_MESSAGE);if(choice==JOptionPane.CANCEL_OPTION||choice==JOptionPane.CLOSED_OPTION)return false;if(choice==JOptionPane.YES_OPTION)try{project.save(session.projectFile);session.dirty=false;DesktopMain.remember(session);updateTitle();}catch(Exception e){error(e);return false;}return true;}
        private void attemptClose(){if(confirmLeave()){stopPlaybacks();dispose();}}
        private void attemptExit(){if(confirmLeave()){stopPlaybacks();DesktopMain.exitApplication();}}
        private void browseNpcs(){new NpcBrowserDialog(this,session.cacheDirectory,entry->{if(!confirmLeave())return;try{stopPlaybacks();DesktopSession next;if(session.transientDesktop)next=DesktopWorkflow.transientSession(session.cacheDirectory,session.exportDirectory,entry.id);else{Path selected=DesktopMain.chooseProject(this,true);if(selected==null)return;next=DesktopWorkflow.create(session.cacheDirectory,selected,session.exportDirectory,entry.id);}DesktopMain.openSession(this,next);}catch(Exception e){error(e);}}).setVisible(true);}
