            timeline.setLayoutOrientation(JList.HORIZONTAL_WRAP);timeline.setVisibleRowCount(-1);timeline.setFixedCellWidth(200);timeline.setFixedCellHeight(214);
            timeline.setCellRenderer((list,value,index,isSelected,focus)->{JLabel label=new JLabel(value.toString(),value.icon,JLabel.CENTER);label.setHorizontalTextPosition(JLabel.CENTER);label.setVerticalTextPosition(JLabel.BOTTOM);label.setOpaque(true);label.setBackground(isSelected?new Color(255,220,150):value.suggestion?new Color(230,210,245):list.getBackground());return label;});
            timeline.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&timeline.getSelectedValue()!=null){updatingScrubber=true;scrubber.setValue((int)timeline.getSelectedValue().timeMillis);updatingScrubber=false;selectAt(scrubber.getValue());}});timeline.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){if(e.getClickCount()==2)assignSelectedCell();}});
