            JPanel outer=new JPanel(new BorderLayout());outer.setBorder(BorderFactory.createTitledBorder("Final RSC sprite sheet"));JPanel grid=new JPanel(new GridLayout(4,7,4,4));grid.add(new JLabel("Pose / view"));for(String label:TargetSheet.COLUMN_LABELS)grid.add(new JLabel(label));
