        private JPanel finalPreviewControls(){JPanel outer=new JPanel();outer.setLayout(new BoxLayout(outer,BoxLayout.Y_AXIS));JPanel playback=new JPanel(new FlowLayout(FlowLayout.LEFT));assembledPlay.setFont(assembledPlay.getFont().deriveFont(java.awt.Font.BOLD,assembledPlay.getFont().getSize2D()+2));assembledPlay.addActionListener(e->toggleAssembledPlayback());playback.add(assembledPlay);playback.add(new JLabel("Selected direction"));outer.add(playback);JPanel colors=new JPanel(new FlowLayout(FlowLayout.LEFT,3,2));backgroundSwatch.setOpaque(true);backgroundSwatch.setBackground(previewBackground);backgroundSwatch.setToolTipText("Preview only; never written to the sprite or project");backgroundSwatch.addActionListener(e->choosePreviewBackground());colors.add(backgroundSwatch);colors.add(backgroundButton("Black",Color.BLACK));colors.add(backgroundButton("White",Color.WHITE));colors.add(backgroundButton("Gray",new Color(96,96,96)));colors.add(backgroundButton("Grass",new Color(62,112,55)));colors.add(backgroundButton("Custom…",null));outer.add(colors);return outer;}
