        private void exportSheet(){DesktopExportPlan plan=session.transientDesktop?DesktopExportPlan.forNpc(session.exportDirectory,project.npcId,workspace.npc.name):DesktopExportPlan.legacy(session.exportDirectory,project.npcId);if(plan.wouldOverwrite()&&JOptionPane.showConfirmDialog(this,"Existing output for this NPC will be replaced:\n"+plan.png+"\n"+plan.manifest,"Replace Existing Export?",JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE)!=JOptionPane.YES_OPTION)return;SpriteProject snapshot=project.copy();long version=editVersion;tasks.submit("Exporting 18-frame sheet…",()->{if(!session.transientDesktop)snapshot.save(session.projectFile);new SheetExporter().export(workspace,snapshot,plan);DesktopMain.remember(session);return plan;},result->{if(version==editVersion)session.dirty=false;updateTitle();JOptionPane.showMessageDialog(this,"Export complete.\n\nPNG:\n"+result.png+"\n\nProvenance:\n"+result.manifest,"Export Complete",JOptionPane.INFORMATION_MESSAGE);},this::error);}
        private void updateManualControls(JPanel panel){panel.setVisible(manualOverride.isSelected());panel.getParent().revalidate();}
        private void sourceRoleChanged(){if(syncingSourceControls)return;sourceSelection.role((AnimationSourceSelection.Role)animationRole.getSelectedItem());updateSourceControls();loadSelectedAnimation();}
        private void updateSourceControls(){animationSourceLabel.setText(sourceSelection.displayLabel());int id=sourceSelection.sequenceId();if(id>=0)manualSequenceId.setValue(id);updateSourceInfo();}
        private void useCombatCandidate(){CombatCandidate candidate=(CombatCandidate)combatCandidates.getSelectedItem();if(candidate!=null)selectRoleAndAssign(AnimationSourceSelection.Role.COMBAT,candidate.sequenceId);}
        private void useManualSequence(){selectRoleAndAssign(sourceSelection.role(),(Integer)manualSequenceId.getValue());}
        private void selectRoleAndAssign(AnimationSourceSelection.Role role,int id){syncingSourceControls=true;sourceSelection.role(role);animationRole.setSelectedItem(role);syncingSourceControls=false;if(sourceSelection.assignSelectedRole(id))markDirty();updateSourceControls();loadSelectedAnimation();}
        private void directionChanged(){int column=sourceDirection.getSelectedIndex();if(column<0)return;sourceSelection.directionColumn(column);if(loaded!=null)loadSelectedAnimation();refreshCells();}
        private void loadSelectedAnimation(){
            int id=sourceSelection.sequenceId(),column=sourceDirection.getSelectedIndex(),request=++timelineRequest;AnimationSourceSelection.Role role=sourceSelection.role();boolean keyframes=keyframesOnly.isSelected(),tween=project.tweening;SpriteProject assignmentSnapshot=project.copy();loaded=null;selectedPose=null;timelineModel.clear();updateSourceControls();if(id<0){sourceInfo.setText(role.label+" was not discovered. Choose a combat suggestion or enable the advanced manual override.");status.setText(role.label+" unavailable");return;}VisualSettings visual=copy(project.visual);double yaw=SheetDirection.yawDegrees(column);tasks.submit("Rendering "+role.label+"…",()->{Sequence530 sequence=workspace.cache.loadSequence(id);java.util.List<FrameSample> samples=AnimationTimeline.selectableSamples(sequence,keyframes);java.util.List<AutomaticPoseSuggestions.Marker> markers=AutomaticPoseSuggestions.markers(assignmentSnapshot,sequence);java.util.List<net.runelite.cache.definitions.ModelDefinition> models=new java.util.ArrayList<>();java.util.List<StaticRenderer.View> views=new java.util.ArrayList<>();for(FrameSample sample:samples){net.runelite.cache.definitions.ModelDefinition model=workspace.pose(new PoseSelection(sample,"timeline"),tween);models.add(model);views.add(new StaticRenderer.View(model,yaw));}StaticRenderer.Viewport viewport=renderer.fitStyled(views,workspace.npc,visual);java.util.List<FrameChoice> frames=new java.util.ArrayList<>();for(int i=0;i<samples.size();i++){FrameSample sample=samples.get(i);BufferedImage image=renderer.renderStyled(List.of(models.get(i)),workspace.npc,yaw,viewport,visual,workspace.textures);frames.add(new FrameChoice(sample,AutomaticPoseSuggestions.labelsAt(markers,sample),icon(image,150,false)));}return new TimelineResult(sequence,frames);},result->{if(request!=timelineRequest||sourceSelection.role()!=role||sourceSelection.sequenceId()!=id)return;loaded=result.sequence;timelineModel.clear();for(FrameChoice frame:result.frames)timelineModel.addElement(frame);scrubber.setMaximum((int)Math.max(0,loaded.totalMillis()-20));scrubber.setMinorTickSpacing(20);scrubber.setSnapToTicks(true);updatingScrubber=true;scrubber.setValue(0);updatingScrubber=false;if(!timelineModel.isEmpty())timeline.setSelectedIndex(0);else selectAt(0);updateSourceInfo();status.setText(role.label+" loaded — "+result.frames.size()+(keyframes?" keyframes":" selectable 20 ms poses")+" — "+SheetDirection.label(column));},e->{if(request==timelineRequest&&sourceSelection.role()==role&&sourceSelection.sequenceId()==id)error(e);});
        }
        private void selectAt(long millis){if(loaded==null)return;selectedPose=new PoseSelection(AnimationTimeline.sample(loaded,millis),"timeline");updateSourceInfo();}
        private void updateSourceInfo(){String position=selectedPose==null||loaded==null?"Select a pose":"Frame "+selectedPose.frameIndex+", cycle "+selectedPose.cycleOffset+", "+selectedPose.timeMillis+" ms, "+SheetDirection.label(sourceSelection.directionColumn());sourceInfo.setText(sourceSelection.role().label+" · "+position+" (sequence "+sourceSelection.sequenceId()+")");}
        private void toggleAssembledPlayback(){
            if(assembledClock.isPlaying()){assembledClock.pause();assembledPlay.setText("Play final RSC loop");playbackTimer.stop();return;}
            int column=selectedColumn;long version=editVersion;
            if(assembledRender!=null&&assembledRender.column==column&&assembledRender.editVersion==version){assembledClock.play();assembledPlay.setText("Pause final RSC loop");playbackTimer.start();playbackTick();return;}
            TargetSheet snapshot=project.copy().sheet;VisualSettings visual=copy(project.visual);boolean tween=project.tweening;
            tasks.submit("Preparing final "+SheetDirection.label(column)+" playback…",()->renderAssembled(snapshot,column,visual,tween,version),rendered->{if(version!=editVersion||column!=selectedColumn)return;assembledRender=rendered;assembledClock.stop();assembledClock.play();assembledPlay.setText("Pause final RSC loop");playbackTimer.start();showAssembledFrame();},this::playbackError);
        }
        private AssembledRender renderAssembled(TargetSheet sheet,int column,VisualSettings visual,boolean tween,long version)throws IOException{
            AssembledPlayback.Plan plan=AssembledPlayback.plan(sheet,column,pose->{try{Sequence530 sequence=workspace.cache.loadSequence(pose.sequenceId);if(pose.frameIndex<0||pose.frameIndex>=sequence.durations.length)throw new IllegalArgumentException("frame index outside sequence");return sequence.durations[pose.frameIndex]*20L;}catch(IOException e){throw new PlaybackLoadException(e);}});
            net.runelite.cache.definitions.ModelDefinition[][] sheetModels=new net.runelite.cache.definitions.ModelDefinition[3][6];java.util.List<StaticRenderer.View> views=new java.util.ArrayList<>();for(int row=0;row<3;row++)for(int col=0;col<6;col++){PoseSelection pose=sheet.cells[row][col].pose;if(pose==null)throw new IllegalStateException("unassigned "+TargetSheet.ROW_LABELS[row]+" / "+SheetDirection.label(col)+" cell");try{net.runelite.cache.definitions.ModelDefinition model=workspace.pose(pose,tween);sheetModels[row][col]=model;views.add(new StaticRenderer.View(model,SheetDirection.yawDegrees(col)));}catch(IOException e){throw new PlaybackLoadException(e);}}
            StaticRenderer.Viewport viewport=renderer.fitStyled(views,workspace.npc,visual);java.util.List<BufferedImage> images=new java.util.ArrayList<>();for(AssembledPlayback.Step step:plan.steps)images.add(renderer.renderStyled(List.of(sheetModels[step.row][column]),workspace.npc,SheetDirection.yawDegrees(column),viewport,visual,workspace.textures));return new AssembledRender(column,version,plan,List.copyOf(images));
        }
        private void playbackTick(){
            if(assembledClock.isPlaying()&&assembledRender!=null)showAssembledFrame();
            else playbackTimer.stop();
        }
        private void showAssembledFrame(){int index=assembledRender.plan.stepIndexAt(assembledClock.elapsedMillis());AssembledPlayback.Step step=assembledRender.plan.steps.get(index);showFinalImage(assembledRender.images.get(index),TargetSheet.ROW_LABELS[step.row]+" — "+SheetDirection.label(assembledRender.column));}
        private void playbackError(Exception e){stopPlaybacks();error(e instanceof PlaybackLoadException&&e.getCause() instanceof Exception?(Exception)e.getCause():e);}
        private void stopPlaybacks(){assembledClock.stop();playbackTimer.stop();assembledPlay.setText("Play final RSC loop");}
        private void closePlayback(){stopPlaybacks();assembledClock.close();}
        private void suggest(){int standing=project.standingSequenceId,walking=project.walkingSequenceId,combat=project.combatSequenceId;tasks.submit("Preparing pose suggestions…",()->{SuggestionSet out=new SuggestionSet();if(standing>=0)out.standing=AutomaticPoseSuggestions.standing(workspace.cache.loadSequence(standing));if(walking>=0){Sequence530 sequence=workspace.cache.loadSequence(walking);out.left=AutomaticPoseSuggestions.leftStep(sequence);out.right=AutomaticPoseSuggestions.rightStep(sequence);}if(combat>=0)out.combat=AutomaticPoseSuggestions.combat(workspace.cache.loadSequence(combat));return out;},out->{boolean changed=false;if(out.standing!=null)for(int c=0;c<5;c++)changed|=project.sheet.suggest(0,c,out.standing);if(out.left!=null)for(int c=0;c<5;c++){changed|=project.sheet.suggest(1,c,out.left);changed|=project.sheet.suggest(2,c,out.right);}if(out.combat!=null)for(int r=0;r<3;r++)changed|=project.sheet.suggest(r,5,out.combat[r]);project.sheet.suggestCombatStandingFromSide();if(changed)markDirty();refreshCells();if(loaded!=null)loadSelectedAnimation();},this::error);}
        private void refreshCells(){if(cellPanels[0][0]==null)return;PoseSelection[][] poses=new PoseSelection[3][6];for(int r=0;r<3;r++)for(int c=0;c<6;c++)poses[r][c]=project.sheet.cells[r][c].pose==null?null:project.sheet.cells[r][c].pose.copy();PoseSelection actual=poses[selectedRow][selectedColumn]==null?(selectedPose==null?null:selectedPose.copy()):poses[selectedRow][selectedColumn];int actualColumn=selectedColumn;VisualSettings visual=copy(project.visual);boolean tween=project.tweening,mirror=project.mirroredPreview;tasks.submitLatest("Rendering previews…",()->renderBatch(poses,actual,actualColumn,visual,tween),batch->{for(int r=0;r<3;r++)for(int c=0;c<6;c++)cellPanels[r][c].apply(batch.images[r][c],batch.errors[r][c],mirror);if(batch.actual==null){finalPreviewImage=null;actualPreview.setIcon(null);actualPreview.setText(actual==null?"Select a pose":"Unsupported: "+batch.actualError);}else showFinalImage(batch.actual,TargetSheet.ROW_LABELS[selectedRow]+" — "+SheetDirection.label(selectedColumn));},this::error);}
        private void showFinalImage(BufferedImage image,String label){finalPreviewImage=image;actualPreview.setText(label);actualPreview.setIcon(new ImageIcon(PreviewCompositor.over(image,previewBackground,project.mirroredPreview)));actualPreview.setHorizontalTextPosition(JLabel.CENTER);actualPreview.setVerticalTextPosition(JLabel.BOTTOM);}
        private RenderBatch renderBatch(PoseSelection[][] poses,PoseSelection actual,int actualColumn,VisualSettings visual,boolean tween)throws IOException{java.util.List<StaticRenderer.View> views=new java.util.ArrayList<>();ModelDefinitionHolder[][] models=new ModelDefinitionHolder[3][6];RenderBatch batch=new RenderBatch();for(int r=0;r<3;r++)for(int c=0;c<6;c++)if(poses[r][c]!=null)try{net.runelite.cache.definitions.ModelDefinition model=workspace.pose(poses[r][c],tween);models[r][c]=new ModelDefinitionHolder(model);views.add(new StaticRenderer.View(model,SheetDirection.yawDegrees(c)));}catch(Exception e){models[r][c]=new ModelDefinitionHolder(e);}net.runelite.cache.definitions.ModelDefinition actualModel=null;if(actual!=null)try{actualModel=workspace.pose(actual,tween);if(views.isEmpty())views.add(new StaticRenderer.View(actualModel,SheetDirection.yawDegrees(actualColumn)));}catch(Exception e){batch.actualError=e.getMessage();}StaticRenderer.Viewport viewport=views.isEmpty()?null:renderer.fitStyled(views,workspace.npc,visual);for(int r=0;r<3;r++)for(int c=0;c<6;c++){ModelDefinitionHolder holder=models[r][c];if(holder==null)continue;if(holder.error!=null){batch.errors[r][c]=holder.error.getMessage();continue;}try{batch.images[r][c]=renderer.renderStyled(List.of(holder.model),workspace.npc,SheetDirection.yawDegrees(c),viewport,visual,workspace.textures);}catch(Exception e){batch.errors[r][c]=e.getMessage();}}if(actualModel!=null)try{batch.actual=renderer.renderStyled(List.of(actualModel),workspace.npc,SheetDirection.yawDegrees(actualColumn),viewport,visual,workspace.textures);}catch(Exception e){batch.actualError=e.getMessage();}return batch;}
        private void assignSelectedCell(){if(selectedPose!=null){project.sheet.override(selectedRow,selectedColumn,selectedPose);markDirty();refreshCells();}}
        private void setSharedRow(int row){if(selectedPose!=null){project.sheet.assignShared(row,selectedPose);project.sheet.suggestCombatStandingFromSide();markDirty();refreshCells();}}
        private void installShortcuts(){bind("ENTER","assign",this::assignSelectedCell);bind("ctrl 1","row0",()->setSharedRow(0));bind("ctrl 2","row1",()->setSharedRow(1));bind("ctrl 3","row2",()->setSharedRow(2));bind("L","lock",()->{TargetSheet.Cell cell=project.sheet.cells[selectedRow][selectedColumn];cell.locked=!cell.locked;markDirty();refreshCells();});bind("BACK_SPACE","shared",()->{project.sheet.clearOverride(selectedRow,selectedColumn);markDirty();refreshCells();});}
        private void bind(String stroke,String name,Runnable action){getRootPane().getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke(stroke),name);getRootPane().getActionMap().put(name,new AbstractAction(){public void actionPerformed(java.awt.event.ActionEvent e){action.run();}});}
        private final class CellPanel extends JPanel {final int row,col;final JLabel preview=new JLabel("Empty",JLabel.CENTER);final JCheckBox lock=new JCheckBox("Lock");CellPanel(int row,int col){this.row=row;this.col=col;setLayout(new BorderLayout());setPreferredSize(new Dimension(135,190));add(preview,BorderLayout.CENTER);add(lock,BorderLayout.SOUTH);lock.addActionListener(e->{project.sheet.cells[row][col].locked=lock.isSelected();markDirty();});MouseAdapter select=new MouseAdapter(){public void mouseClicked(MouseEvent e){selectedRow=row;selectedColumn=col;assembledClock.stop();assembledPlay.setText("Play final RSC loop");if(e.getClickCount()==2)assignSelectedCell();if(sourceDirection.getSelectedIndex()!=col)sourceDirection.setSelectedIndex(col);else refreshCells();}};addMouseListener(select);preview.addMouseListener(select);apply(null,null,false);}
            void apply(BufferedImage image,String error,boolean mirror){TargetSheet.Cell cell=project.sheet.cells[row][col];lock.setSelected(cell.locked);Color state=cell.locked?new Color(180,55,55):cell.override?new Color(50,110,200):cell.pose!=null&&"suggestion".equals(cell.pose.source)?new Color(150,75,180):cell.pose!=null?new Color(50,145,85):Color.GRAY;javax.swing.border.Border stateBorder=BorderFactory.createTitledBorder(BorderFactory.createLineBorder(state,2),cell.pose==null?"Empty":cell.locked?"LOCKED":cell.override?"OVERRIDE":"suggestion".equals(cell.pose.source)?"SUGGESTION":"SHARED");setBorder(row==selectedRow&&col==selectedColumn?BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Color.ORANGE,3),stateBorder):stateBorder);if(cell.pose==null){preview.setIcon(null);preview.setText("Double-click to assign");return;}if(error!=null){preview.setIcon(null);preview.setText("UNSUPPORTED: "+error);setToolTipText(error);return;}if(image==null){preview.setIcon(null);preview.setText("Rendering…");return;}preview.setIcon(icon(image,112,mirror));preview.setText("S"+cell.pose.sequenceId+" F"+cell.pose.frameIndex+" +"+cell.pose.cycleOffset);preview.setHorizontalTextPosition(JLabel.CENTER);preview.setVerticalTextPosition(JLabel.BOTTOM);setToolTipText(cell.pose.source+"; "+(cell.locked?"locked":"editable"));}
        }
        private <T> void runAsync(String label,DesktopTaskRunner.Task<T> action,java.util.function.Consumer<T> success){tasks.submit(label,action,success,this::error);}
        private void error(Exception e){status.setText("Error: "+root(e));JOptionPane.showMessageDialog(this,root(e),"Error",JOptionPane.ERROR_MESSAGE);}
        private static String root(Throwable e){while(e.getCause()!=null)e=e.getCause();return e.toString();}
